11: export function normalizeHorizontal(direction: Vec3): Vec3 | null {
12:   const length = Math.hypot(direction.x, direction.z);
13:   if (length < 1e-8) return null;
14:   return { x: direction.x / length, y: 0, z: direction.z / length };
